  # 2)clean edges
  E &lt;- data[['edge_table']] |&gt;
    mutate(uid = as.character(uid), a__uid = as.character(a__uid)) |&gt;
    filter(uid %in% N_uids, a__uid %in% N_uids) |&gt;
    relocate(a__uid, .after = uid)

  is_directed &lt;- if(!is.null(directed_type)) TRUE else FALSE

  E = if(exclude_edge_with_self) E |&gt; filter(uid != a__uid) else E
  E = if(is_directed) E |&gt; filter(!(a__author_position == directed_type)) else E

  N_uids &lt;- E |&gt; distinct(uid) |&gt; pull()

  # 3) build graph from edge table
  g &lt;- graph_from_data_frame(
      E,
      directed = !is_directed,
      # vertices = tibble(name = N_uids)
    )

  # (optional) excludes isolates
  if (exclude_isolates) {
      deg &lt;- degree(g, mode = if (is_directed) "all" else "total")
      g   &lt;- induced_subgraph(g, vids = which(deg &gt; 0))
    }

  N_uids &lt;- igraph::V(g)$name
  n      &lt;- length(N_uids)

  # 4) adjacency matrix
  A &lt;- igraph::as_adjacency_matrix(g, sparse = TRUE)
  if (!is_directed) A &lt;- Matrix::forceSymmetric(A, uplo = "U")

  # 5) incidence matrix
  el &lt;- igraph::as_data_frame(g, what = "edges")
  m  &lt;- nrow(el)

  if (m == 0L) {
    B &lt;- sparseMatrix(
      i = integer(), j = integer(), x = numeric(),
      dims     = c(n, 0),
      dimnames = list(N_uids, character())
    )
  } else {
    tail_idx &lt;- match(el$from, N_uids)
    head_idx &lt;- match(el$to,   N_uids)

    vals &lt;- if (is_directed && sign_incidence) {
      c(rep(-1, m), rep(+1, m))
    } else {
      rep(1, 2L * m)
    }

    B &lt;- sparseMatrix(
      i        = c(tail_idx, head_idx),
      j        = rep(seq_len(m), each = 2L),
      x        = vals,
      dims     = c(n, m),
      dimnames = list(N_uids, paste0("e", seq_len(m)))
    )
  }

  # 6) ego × alter counts (still counts of edges in raw Eclean)
  E2 &lt;- E |&gt;
    filter(uid %in% N_uids, a__uid %in% N_uids) |&gt;
    mutate(
      uid    = factor(uid,    levels = N_uids),
      a__uid = factor(a__uid, levels = N_uids)
    )

  E_mat &lt;- if (nrow(E2) == 0L) {
    Matrix::Matrix(
      0,
      nrow = n, ncol = n,
      dimnames = list(N_uids, N_uids),
      sparse   = TRUE
    )
  } else {
    Matrix::Matrix(
      stats::xtabs(~ uid + a__uid, E2),
      sparse = TRUE
    )
  }

  E = E2 |&gt; distinct(uid, a__uid, .keep_all = TRUE)

  # 7) filter demographics to nodes kept
  D = data[['demographics']] |&gt; filter(uid %in% N_uids)

  return(list(
    graph = g,
    A     = A,
    B     = B,
    D     = D,
    E     = E,
    E_mat = E_mat
  ))
}

