describe_categorical &lt;- function(data, vars) {
  data |&gt;
    select(all_of(vars)) |&gt;
    # long format: variable + value
    tidyr::pivot_longer(
      cols      = everything(),
      names_to  = "variable",
      values_to = "value"
    ) |&gt;
    group_by(variable) |&gt;
    mutate(
      n_total   = n(),
      n_missing = sum(is.na(value)),
      n_nonmiss = n_total - n_missing
    ) |&gt;
    filter(!is.na(value)) |&gt;
    count(variable, value, n_total, n_missing, n_nonmiss, name = "n") |&gt;
    group_by(variable) |&gt;
    mutate(
      prop        = n / n_nonmiss,
      prop_missing = n_missing / n_total
    ) |&gt;
    ungroup() |&gt;
    arrange(variable, desc(n))
}

