compute_network_statistics &lt;- function(nets) {
  g &lt;- nets$graph
  stopifnot(inherits(g, "igraph"))

  is_dir &lt;- igraph::is_directed(g)

  # Optionally copy attributes from nets$D onto vertices
  if (!is.null(nets$D) && "uid" %in% colnames(nets$D)) {
    D   &lt;- nets$D
    idx &lt;- match(igraph::V(g)$name, D$uid)

    for (v in c("gender", "origin", "university", "position")) {
      if (v %in% colnames(D)) {
        vals &lt;- D[[v]][idx]
        g &lt;- igraph::set_vertex_attr(g, v, value = vals)
      }
    }
  }

  # --- Core structural properties (full graph) ---
  comp  &lt;- igraph::components(g)
  gc_id &lt;- which.max(comp$csize)
  gc_v  &lt;- which(comp$membership == gc_id)
  g_gc  &lt;- igraph::induced_subgraph(g, gc_v)

  n_nodes &lt;- igraph::vcount(g)
  n_edges &lt;- igraph::ecount(g)

  density &lt;- igraph::edge_density(g, loops = FALSE)
  avg_degree &lt;- mean(
    igraph::degree(g, mode = if (is_dir) "all" else "total")
  )

  trans_global &lt;- igraph::transitivity(
    g,
    type = if (is_dir) "global" else "globalundirected"
  )

  trans_local_vec &lt;- igraph::transitivity(
    g,
    type = if (is_dir) "local" else "localundirected"
  )
  trans_local_mean &lt;- mean(trans_local_vec, na.rm = TRUE)

  avg_path_gc &lt;- suppressWarnings(
    igraph::mean_distance(g_gc, directed = is_dir)
  )
  diam_gc &lt;- suppressWarnings(
    igraph::diameter(g_gc, directed = is_dir, unconnected = FALSE)
  )

  # --- Simple small-world indicators via ER baseline (full graph) ---
  p &lt;- density
  if (is.finite(p) && !is.na(p) && p &gt; 0) {
    g_rand &lt;- igraph::sample_gnp(
      n       = n_nodes,
      p       = p,
      directed = is_dir,
      loops   = FALSE
    )

    trans_rand &lt;- igraph::transitivity(
      g_rand,
      type = if (is_dir) "global" else "globalundirected"
    )
    avg_path_rand &lt;- suppressWarnings(
      igraph::mean_distance(g_rand, directed = is_dir)
    )

    smallworld_C_ratio &lt;- trans_global / trans_rand
    smallworld_L_ratio &lt;- avg_path_gc / avg_path_rand
  } else {
    smallworld_C_ratio &lt;- NA_real_
    smallworld_L_ratio &lt;- NA_real_
  }

  overall &lt;- tibble::tibble(
    # Size / connectivity
    attribute            = "scholars",
    level                = "all",
    n_nodes              = n_nodes,
    n_edges              = n_edges,
    density              = density,
    avg_degree           = avg_degree,

    # Clustering & paths
    transitivity_global       = trans_global,
    transitivity_local_mean   = trans_local_mean,
    avg_path_length_giantcomp = avg_path_gc,
    diameter_giantcomp        = diam_gc,

    # Small-world-ish indicators (relative to ER baseline)
    smallworld_C_ratio = smallworld_C_ratio,
    smallworld_L_ratio = smallworld_L_ratio
  )

  # --- Helper: compute the same stats on an induced subgraph ---
  compute_structural_stats &lt;- function(g_sub) {
    if (igraph::vcount(g_sub) &lt; 2 || igraph::ecount(g_sub) &lt; 1) {
      return(
        list(
          n_nodes                    = igraph::vcount(g_sub),
          n_edges                    = igraph::ecount(g_sub),
          density                    = NA_real_,
          avg_degree                 = NA_real_,
          transitivity_global        = NA_real_,
          transitivity_local_mean    = NA_real_,
          avg_path_length_giantcomp  = NA_real_,
          diameter_giantcomp         = NA_real_,
          smallworld_C_ratio         = NA_real_,
          smallworld_L_ratio         = NA_real_
        )
      )
    }

    comp_sub  &lt;- igraph::components(g_sub)
    gc_id_sub &lt;- which.max(comp_sub$csize)
    gc_v_sub  &lt;- which(comp_sub$membership == gc_id_sub)
    g_gc_sub  &lt;- igraph::induced_subgraph(g_sub, gc_v_sub)

    n_nodes_sub &lt;- igraph::vcount(g_sub)
    n_edges_sub &lt;- igraph::ecount(g_sub)

    density_sub &lt;- igraph::edge_density(g_sub, loops = FALSE)
    avg_degree_sub &lt;- mean(
      igraph::degree(g_sub, mode = if (is_dir) "all" else "total")
    )

    trans_global_sub &lt;- igraph::transitivity(
      g_sub,
      type = if (is_dir) "global" else "globalundirected"
    )

    trans_local_vec_sub &lt;- igraph::transitivity(
      g_sub,
      type = if (is_dir) "local" else "localundirected"
    )
    trans_local_mean_sub &lt;- mean(trans_local_vec_sub, na.rm = TRUE)

    avg_path_gc_sub &lt;- suppressWarnings(
      igraph::mean_distance(g_gc_sub, directed = is_dir)
    )
    diam_gc_sub &lt;- suppressWarnings(
      igraph::diameter(g_gc_sub, directed = is_dir, unconnected = FALSE)
    )

    # Small-world baseline within group
    p_sub &lt;- density_sub
    if (is.finite(p_sub) && !is.na(p_sub) && p_sub &gt; 0) {
      g_rand_sub &lt;- igraph::sample_gnp(
        n       = n_nodes_sub,
        p       = p_sub,
        directed = is_dir,
        loops   = FALSE
      )
      trans_rand_sub &lt;- igraph::transitivity(
        g_rand_sub,
        type = if (is_dir) "global" else "globalundirected"
      )
      avg_path_rand_sub &lt;- suppressWarnings(
        igraph::mean_distance(g_rand_sub, directed = is_dir)
      )

      smallworld_C_ratio_sub &lt;- trans_global_sub / trans_rand_sub
      smallworld_L_ratio_sub &lt;- avg_path_gc_sub / avg_path_rand_sub
    } else {
      smallworld_C_ratio_sub &lt;- NA_real_
      smallworld_L_ratio_sub &lt;- NA_real_
    }

    list(
      n_nodes                    = n_nodes_sub,
      n_edges                    = n_edges_sub,
      density                    = density_sub,
      avg_degree                 = avg_degree_sub,
      transitivity_global        = trans_global_sub,
      transitivity_local_mean    = trans_local_mean_sub,
      avg_path_length_giantcomp  = avg_path_gc_sub,
      diameter_giantcomp         = diam_gc_sub,
      smallworld_C_ratio         = smallworld_C_ratio_sub,
      smallworld_L_ratio         = smallworld_L_ratio_sub
    )
  }

  # --- Helper: apply those stats by levels of a vertex attribute ---
  compute_by_attribute &lt;- function(attr_name) {
    vals &lt;- igraph::vertex_attr(g, attr_name)
    if (is.null(vals)) {
      return(tibble::tibble())
    }

    vals_chr &lt;- as.character(vals)
    levels_attr &lt;- sort(unique(vals_chr[!is.na(vals_chr)]))
    if (length(levels_attr) == 0) {
      return(tibble::tibble())
    }

    res &lt;- lapply(levels_attr, function(lv) {
      vids &lt;- which(vals_chr == lv)
      if (length(vids) &lt; 2) {
        stats &lt;- compute_structural_stats(
          igraph::induced_subgraph(g, vids)
        )
      } else {
        stats &lt;- compute_structural_stats(
          igraph::induced_subgraph(g, vids)
        )
      }

      tibble::tibble(
        attribute                 = attr_name,
        level                     = lv,
        n_nodes                   = stats$n_nodes,
        n_edges                   = stats$n_edges,
        density                   = stats$density,
        avg_degree                = stats$avg_degree,
        transitivity_global       = stats$transitivity_global,
        transitivity_local_mean   = stats$transitivity_local_mean,
        avg_path_length_giantcomp = stats$avg_path_length_giantcomp,
        diameter_giantcomp        = stats$diameter_giantcomp,
        smallworld_C_ratio        = stats$smallworld_C_ratio,
        smallworld_L_ratio        = stats$smallworld_L_ratio
      )
    })

    bind_rows(res)
  }

  by_group &lt;- bind_rows(
    compute_by_attribute("gender"),
    compute_by_attribute("origin"),
    compute_by_attribute("position"),
    compute_by_attribute("university")
  )

  # Return both
  list(
    overall  = overall,
    by_group = by_group
  )
}


